            limit: 4,
            themes: ["Week 1: Product Launch", "Week 2: Social Proof & Testimonials", "Week 3: Behind the Scenes", "Week 4: Interactive Q&A"],
            slots: []
        };

        let currentSlotId = null;
        let targetWeek = null;
        let targetDay = null;

        // Element caches
        const container = document.getElementById('calendarContainer');
        const modal = document.getElementById('briefModal');
        const modalChannel = document.getElementById('modalChannel');
        const modalPostTitle = document.getElementById('modalPostTitle');
        const modalCopy = document.getElementById('modalCopy');
        const themesInput = document.getElementById('themesInput');
        const weeklyLimitInput = document.getElementById('weeklyLimitInput');
        const channelsInput = document.getElementById('channelsInput');

        function init() {
            weeklyLimitInput.value = plannerData.limit;
            themesInput.value = (plannerData.themes || []).join('\n');

            // Event Registry mapping safely to avoid event attributes
            document.getElementById('refreshBtn').addEventListener('click', processSetupSync);
            document.getElementById('saveBtn').addEventListener('click', saveSlotData);
            document.getElementById('deleteBtn').addEventListener('click', deleteSlotData);
            document.getElementById('closeBtn').addEventListener('click', closeModalView);
            document.getElementById('copyBtn').addEventListener('click', executionCopyBridge);
            document.getElementById('downloadBtn').addEventListener('click', triggerFileDownload);

            renderCalendarMatrix();
        }

        function processSetupSync() {
            plannerData.limit = parseInt(weeklyLimitInput.value) || 4;
            plannerData.themes = themesInput.value.split('\n');
            saveStateToStorage();
            renderCalendarMatrix();
        }

        function saveStateToStorage() {
            localStorage.setItem('secure_planner_data_v2', JSON.stringify(plannerData));
        }

        function renderCalendarMatrix() {
            container.textContent = '';
            const currentLimit = plannerData.limit;

            for (let w = 1; w <= 4; w++) {
                const currentWeekSlots = plannerData.slots.filter(s => s.week === w);
                const volumeCount = currentWeekSlots.length;
                const isOverloaded = volumeCount > currentLimit;

                // Week Structural Wrapper
                const weekBlock = document.createElement('div');
                weekBlock.classList.add('week-block');

                // Header Generation
                const weekHeader = document.createElement('div');
                weekHeader.classList.add('week-header');

                const titleSpan = document.createElement('span');
                titleSpan.textContent = `Week ${w}`;
                weekHeader.appendChild(titleSpan);

                const statusBadge = document.createElement('span');
                statusBadge.classList.add('status-badge');

                if (isOverloaded) {
                    statusBadge.classList.add('status-over');
                    statusBadge.textContent = `${volumeCount} / ${currentLimit} Posts — Overload Warning`;
                } else {
                    statusBadge.classList.add('status-ok');
                    statusBadge.textContent = `${volumeCount} / ${currentLimit} Posts Allocated`;
                }
                weekHeader.appendChild(statusBadge);
                weekBlock.appendChild(weekHeader);

                // Add Theme Indicator if configuration contains text
                if (plannerData.themes && plannerData.themes[w - 1]) {
                    const themeBar = document.createElement('div');
                    themeBar.classList.add('theme-indicator');
                    themeBar.textContent = plannerData.themes[w - 1];
                    weekBlock.appendChild(themeBar);
                }

                // Grid mapping
                const daysGrid = document.createElement('div');
                daysGrid.classList.add('days-grid');

                DAYS.forEach(day => {
                    const dayCard = document.createElement('div');
                    dayCard.classList.add('day-card');

                    const dayLabel = document.createElement('div');
                    dayLabel.classList.add('day-name');
                    dayLabel.textContent = day.substring(0, 3);
                    dayCard.appendChild(dayLabel);

                    // Dynamic Slot Injection Area
                    const activeDaySlots = currentWeekSlots.filter(s => s.day === day);
                    activeDaySlots.forEach(slot => {
                        const slotNode = document.createElement('div');
                        slotNode.classList.add('slot');

                        const slotTitleText = document.createElement('div');
                        slotTitleText.classList.add('slot-title');
                        slotTitleText.textContent = `[${slot.channel}] ${slot.title || '(Untitled)'}`;

                        slotNode.appendChild(slotTitleText);
                        slotNode.addEventListener('click', () => initiateEditSequence(slot.id));
                        dayCard.appendChild(slotNode);
                    });

                    // Native Add action instantiation
                    const addBtn = document.createElement('button');
                    addBtn.classList.add('add-btn');
                    addBtn.textContent = '+ Add Item';
                    addBtn.addEventListener('click', () => initiateCreateSequence(w, day));

                    dayCard.appendChild(addBtn);
                    daysGrid.appendChild(dayCard);
                });

                weekBlock.appendChild(daysGrid);
                container.appendChild(weekBlock);
            }
        }

        function populateChannelSelectOptions() {
            modalChannel.textContent = '';
            const targetedChannels = channelsInput.value.split(',').map(c => c.trim()).filter(Boolean);
            targetedChannels.forEach(chan => {
                const optionNode = document.createElement('option');
                optionNode.value = chan;
                optionNode.textContent = chan;
                modalChannel.appendChild(optionNode);
            });
        }

        function initiateCreateSequence(week, day) {
            currentSlotId = null;
            targetWeek = week;
            targetDay = day;

            populateChannelSelectOptions();
            document.getElementById('modalTitle').textContent = `New Entry: Week ${week} - ${day}`;
            modalPostTitle.value = '';
            modalCopy.value = '';
            modal.style.display = 'flex';
        }

        function initiateEditSequence(id) {
            currentSlotId = id;
            const contextSlot = plannerData.slots.find(s => s.id === id);
            if (!contextSlot) return;

            populateChannelSelectOptions();
            document.getElementById('modalTitle').textContent = `Modify Entry: Week ${contextSlot.week} - ${contextSlot.day}`;
            modalChannel.value = contextSlot.channel;
            modalPostTitle.value = contextSlot.title || '';
            modalCopy.value = contextSlot.copy || '';
            modal.style.display = 'flex';
        }

        function closeModalView() {
            modal.style.display = 'none';
        }

        function saveSlotData() {
            const compiledChannel = modalChannel.value || 'General';
            const compiledTitle = modalPostTitle.value;
            const compiledCopy = modalCopy.value;

            if (currentSlotId) {
                const entity = plannerData.slots.find(s => s.id === currentSlotId);
                if (entity) {
                    entity.channel = compiledChannel;
                    entity.title = compiledTitle;
                    entity.copy = compiledCopy;
                }
            } else {
                plannerData.slots.push({
                    id: Date.now(),
                    week: targetWeek,
                    day: targetDay,
                    channel: compiledChannel,
                    title: compiledTitle,
                    copy: compiledCopy
                });
            }

            saveStateToStorage();
            closeModalView();
            renderCalendarMatrix();
        }

        function deleteSlotData() {
            if (currentSlotId) {
                plannerData.slots = plannerData.slots.filter(s => s.id !== currentSlotId);
                saveStateToStorage();
                closeModalView();
                renderCalendarMatrix();
            }
        }

        function buildPayloadString() {
            const cleanChan = modalChannel.value || 'N/A';
            const cleanTitle = modalPostTitle.value || 'Untitled Content';
            const cleanCopy = modalCopy.value || '';
            return `CHANNEL: ${cleanChan}\nTITLE/HOOK: ${cleanTitle}\n\nCONTENT BRIEF:\n${cleanCopy}`;
        }

        function executionCopyBridge() {
            const exportText = buildPayloadString();

            if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard.writeText(exportText)
                    .then(() => alert('Brief safely copied to clipboard.'))
                    .catch(() => fallbackCopyEngine(exportText));
            } else {
                fallbackCopyEngine(exportText);
            }
        }

        function fallbackCopyEngine(text) {
            const temporaryTextArea = document.createElement('textarea');
            temporaryTextArea.value = text;

            // Positioning away from visibility viewport to keep interface layout uniform
            temporaryTextArea.style.position = 'fixed';
            temporaryTextArea.style.top = '-9999px';
            document.body.appendChild(temporaryTextArea);

            temporaryTextArea.focus();
            temporaryTextArea.select();

            try {
                const evaluation = document.execCommand('copy');
                if (evaluation) {
                    alert('Brief safely copied to clipboard via secure fallback mechanism.');
                } else {
                    alert('Copy operation failed. Please copy text context manually.');
                }
            } catch (err) {
                alert('Fallback framework execution error. Please copy text context manually.');
            }

            document.body.removeChild(temporaryTextArea);
        }

        function triggerFileDownload() {
            const rawBody = buildPayloadString();
            const referenceTitle = modalPostTitle.value || 'content_brief';
            const sanitizedFileName = referenceTitle.replace(/[^a-z0-9]/gi, '_').toLowerCase();

            const fileBlob = new Blob([rawBody], { type: 'text/plain;charset=utf-8' });
            const temporaryAnchor = document.createElement('a');

            temporaryAnchor.download = `${sanitizedFileName}_brief.txt`;
            temporaryAnchor.href = window.URL.createObjectURL(fileBlob);
            temporaryAnchor.style.display = 'none';

            document.body.appendChild(temporaryAnchor);
            temporaryAnchor.click();

            window.URL.revokeObjectURL(temporaryAnchor.href);
            document.body.removeChild(temporaryAnchor);
        }

        window.addEventListener('DOMContentLoaded', init);
    </script>
</body>
