                const slots = plannerData.slots.filter(s => s.week === w);
                const block = document.createElement('div');
                block.className = 'week-block';
                const head = document.createElement('div');
                head.className = 'week-header';
                const title = document.createElement('span');
                title.textContent = `Week ${w}`;
                const badge = document.createElement('span');
                badge.className = `status-badge ${slots.length > limit ? 'status-over' : 'status-ok'}`;
                badge.textContent = `${slots.length}/${limit} Posts ${slots.length > limit ? '(Overload)' : ''}`;
                head.appendChild(title);
                head.appendChild(badge);
                block.appendChild(head);

                const grid = document.createElement('div');
                grid.className = 'days-grid';
                DAYS.forEach(d => {
                    const card = document.createElement('div');
                    card.className = 'day-card';
                    const name = document.createElement('div');
                    name.className = 'day-name';
                    name.textContent = d;
                    card.appendChild(name);
                    slots.filter(s => s.day === d).forEach(s => {
                        const slot = document.createElement('div');
                        slot.className = 'slot';
                        slot.textContent = `[${s.channel}] ${s.title}`;
                        slot.addEventListener('click', () => edit(s));
                        card.appendChild(slot);
                    });
                    const add = document.createElement('button');
                    add.className = 'add-btn';
                    add.textContent = '+ Add Item';
                    add.addEventListener('click', () => open(w, d));
                    card.appendChild(add);
                    grid.appendChild(card);
                });
                block.appendChild(grid);
                container.appendChild(block);
            }
        }

        function open(w, d) {
            currentSlotId = null; targetWeek = w; targetDay = d;
            document.getElementById('modalTitle').textContent = `New: W${w} ${d}`;
            document.getElementById('modalChannel').innerHTML = '';
            document.getElementById('channelsInput').value.split(',').forEach(c => {
                const opt = document.createElement('option');
                opt.textContent = c.trim();
                document.getElementById('modalChannel').appendChild(opt);
            });
            modal.style.display = 'flex';
        }

        function edit(s) {
            currentSlotId = s.id;
            open(s.week, s.day);
            document.getElementById('modalChannel').value = s.channel;
            document.getElementById('modalPostTitle').value = s.title;
            document.getElementById('modalCopy').value = s.copy;
        }

        document.getElementById('saveBtn').addEventListener('click', () => {
            if (currentSlotId) {
                const s = plannerData.slots.find(x => x.id === currentSlotId);
                s.channel = document.getElementById('modalChannel').value;
                s.title = document.getElementById('modalPostTitle').value;
                s.copy = document.getElementById('modalCopy').value;
            } else {
                plannerData.slots.push({ id: Date.now(), week: targetWeek, day: targetDay, channel: document.getElementById('modalChannel').value, title: document.getElementById('modalPostTitle').value, copy: document.getElementById('modalCopy').value });
            }
            localStorage.setItem('planner_final', JSON.stringify(plannerData));
            modal.style.display = 'none';
            render();
        });

        document.getElementById('refreshBtn').addEventListener('click', render);
        document.getElementById('closeBtn').addEventListener('click', () => modal.style.display = 'none');
        document.getElementById('deleteBtn').addEventListener('click', () => {
            plannerData.slots = plannerData.slots.filter(s => s.id !== currentSlotId);
            render();
            modal.style.display = 'none';
        });
        render();
    </script>
</body>
</html>

