</head>
<body>

    <div class="section">
        <h1>Setup & Strategy</h1>
        <div class="grid-mobile-stack">
            <div>
                <label for="channelsInput">Channels (comma separated)</label>
                <input type="text" id="channelsInput" value="Instagram, LinkedIn, Newsletter">
            </div>
            <div>
                <label for="weeklyLimitInput">Weekly Max Limit</label>
                <input type="number" id="weeklyLimitInput" value="4">
            </div>
        </div>
        <label for="themesInput">Campaign Themes (One line per week)</label>
        <textarea id="themesInput" rows="4" placeholder="Week 1: Launch Week&#10;Week 2: Social Proof&#10;Week 3: Core Values&#10;Week 4: Offer Details"></textarea>
        <button id="refreshBtn" class="btn-pri" style="margin-top: 12px;">Apply Layout & Setup Settings</button>
    </div>

    <div class="section">
        <h2>4-Week Content Framework</h2>
        <div id="calendarContainer"></div>
    </div>

    <div id="briefModal" class="modal">
        <div class="modal-content">
            <h3 id="modalTitle">Edit Plan Details</h3>

            <label for="modalChannel">Target Channel</label>
            <select id="modalChannel"></select>

            <label for="modalPostTitle">Brief Title / Headline Hook</label>
            <input type="text" id="modalPostTitle">

            <label for="modalCopy">Caption Narrative Copy / Creative Brief</label>
            <textarea id="modalCopy" rows="6"></textarea>

            <div class="btn-group">
                <button id="saveBtn" class="btn-pri">Save Post</button>
                <button id="deleteBtn" class="btn-danger">Delete</button>
                <button id="closeBtn" class="btn-sec">Close</button>
            </div>
            <div class="btn-group">
                <button id="copyBtn" class="btn-sec">📋 Copy Brief</button>
                <button id="downloadBtn" class="btn-sec">💾 Download Brief</button>
            </div>
        </div>
    </div>

    <script>
        const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

        let plannerData = JSON.parse(localStorage.getItem('secure_planner_data_v5')) || {
            limit: 4,
            themes: ["Week 1: Launch Week", "Week 2: Social Proof", "Week 3: Core Values", "Week 4: Offer Details"],
            slots: []
        };

        let currentSlotId = null;
        let targetWeek = null;
        let targetDay = null;

        const container = document.getElementById('calendarContainer');
        const modal = document.getElementById('briefModal');
        const modalChannel = document.getElementById('modalChannel');
        const modalPostTitle = document.getElementById('modalPostTitle');
        const modalCopy = document.getElementById('modalCopy');
        const themesInput = document.getElementById('themesInput');
        const weeklyLimitInput = document.getElementById('weeklyLimitInput');
        const channelsInput = document.getElementById('channelsInput');

        function init() {
            weeklyLimitInput.value = plannerData.limit;
            themesInput.value = (plannerData.themes || []).join('\n');

            document.getElementById('refreshBtn').addEventListener('click', handleSettingsSync);
            document.getElementById('saveBtn').addEventListener('click', saveActiveSlot);
            document.getElementById('deleteBtn').addEventListener('click', removeActiveSlot);
            document.getElementById('closeBtn').addEventListener('click', hideModalOverlay);
            document.getElementById('copyBtn').addEventListener('click', executeClipboardCopy);
            document.getElementById('downloadBtn').addEventListener('click', executeTextDownload);

            renderWorkspaceMatrix();
        }

        function handleSettingsSync() {
            plannerData.limit = parseInt(weeklyLimitInput.value) || 4;
            plannerData.themes = themesInput.value.split('\n');
            persistState();
            renderWorkspaceMatrix();
        }

        function persistState() {
            localStorage.setItem('secure_planner_data_v5', JSON.stringify(plannerData));
        }

        function renderWorkspaceMatrix() {
            container.textContent = '';
            const activeLimit = plannerData.limit;

            for (let w = 1; w <= 4; w++) {
                const globalWeekSlots = plannerData.slots.filter(s => s.week === w);
                const weekTotal = globalWeekSlots.length;
                const allocationExceeded = weekTotal > activeLimit;

                const weekBlock = document.createElement('div');
                weekBlock.classList.add('week-block');

                const weekHeader = document.createElement('div');
                weekHeader.classList.add('week-header');

                const labelSpan = document.createElement('span');
                labelSpan.textContent = `Week ${w}`;
                weekHeader.appendChild(labelSpan);

                const statusBadge = document.createElement('span');
                statusBadge.classList.add('status-badge');
                if (allocationExceeded) {
                    statusBadge.classList.add('status-over');
                    statusBadge.textContent = `${weekTotal} / ${activeLimit} Posts — Overload Warning`;
                } else {
                    statusBadge.classList.add('status-ok');
                    statusBadge.textContent = `${weekTotal} / ${activeLimit} Posts Active`;
                }
                weekHeader.appendChild(statusBadge);
                weekBlock.appendChild(weekHeader);

                if (plannerData.themes && plannerData.themes[w - 1]) {
                    const themeBar = document.createElement('div');
                    themeBar.classList.add('theme-indicator');
                    themeBar.textContent = plannerData.themes[w - 1];
                    weekBlock.appendChild(themeBar);
                }

                const singleColumnContainer = document.createElement('div');
                singleColumnContainer.classList.add('days-grid');

                DAYS.forEach(day => {
                    const dayCard = document.createElement('div');
                    dayCard.classList.add('day-card');

                    const titleNode = document.createElement('div');
                    titleNode.classList.add('day-name');
                    titleNode.textContent = day;
                    dayCard.appendChild(titleNode);

                    const dayTargetSlots = globalWeekSlots.filter(s => s.day === day);
                    dayTargetSlots.forEach(slot => {
                        const cellNode = document.createElement('div');
                        cellNode.classList.add('slot');
                        cellNode.textContent = `[${slot.channel}] ${slot.title || '(Untitled)'}`;
                        cellNode.addEventListener('click', () => triggerSlotModification(slot.id));
                        dayCard.appendChild(cellNode);
                    });

                    const appendBtn = document.createElement('button');
                    appendBtn.classList.add('add-btn');
                    appendBtn.textContent = '+ Add Item';
                    appendBtn.addEventListener('click', () => triggerSlotCreation(w, day));

                    dayCard.appendChild(appendBtn);
                    singleColumnContainer.appendChild(dayCard);
                });

                weekBlock.appendChild(singleColumnContainer);
                container.appendChild(weekBlock);
            }
        }

        function populateChannelSelector() {
            modalChannel.textContent = '';
            const channelArray = channelsInput.value.split(',').map(c => c.trim()).filter(Boolean);
            channelArray.forEach(chan => {
                const optNode = document.createElement('option');
                optNode.value = chan;
                optNode.textContent = chan;
                modalChannel.appendChild(optNode);
            });
        }

        function triggerSlotCreation(week, day) {
            currentSlotId = null;
            targetWeek = week;
            targetDay = day;

            populateChannelSelector();
            document.getElementById('modalTitle').textContent = `New Block: Week ${week} - ${day}`;
            modalPostTitle.value = '';
            modalCopy.value = '';
            modal.style.display = 'flex';
        }

        function triggerSlotModification(id) {
            currentSlotId = id;
            const targetObject = plannerData.slots.find(s => s.id === id);
            if (!targetObject) return;

            populateChannelSelector();
            document.getElementById('modalTitle').textContent = `Modify Block: Week ${targetObject.week} - ${targetObject.day}`;
            modalChannel.value = targetObject.channel;
            modalPostTitle.value = targetObject.title || '';
            modalCopy.value = targetObject.copy || '';
            modal.style.display = 'flex';
        }

        function hideModalOverlay() {
            modal.style.display = 'none';
        }

        function saveActiveSlot() {
            const chosenChannel = modalChannel.value || 'General';
            const chosenTitle = modalPostTitle.value;
            const chosenCopy = modalCopy.value;

            if (currentSlotId) {
                const record = plannerData.slots.find(s => s.id === currentSlotId);
                if (record) {
                    record.channel = chosenChannel;
                    record.title = chosenTitle;
                    record.copy = chosenCopy;
                }
            } else {
                plannerData.slots.push({
                    id: Date.now(),
                    week: targetWeek,
                    day: targetDay,
                    channel: chosenChannel,
                    title: chosenTitle,
                    copy: chosenCopy
                });
            }

            persistState();
            hideModalOverlay();
            renderWorkspaceMatrix();
        }

        function removeActiveSlot() {
            if (currentSlotId) {
                plannerData.slots = plannerData.slots.filter(s => s.id !== currentSlotId);
                persistState();
                hideModalOverlay();
                renderWorkspaceMatrix();
            }
        }

        function serializeBriefString() {
            const rawChannel = modalChannel.value || 'N/A';
            const rawTitle = modalPostTitle.value || 'Untitled Post';
            const rawCopy = modalCopy.value || '';
            return `CHANNEL: ${rawChannel}\nTITLE/HOOK: ${rawTitle}\n\nCONTENT DICTION:\n${rawCopy}`;
        }

        function executeClipboardCopy() {
            const formattedOutputText = serializeBriefString();

            if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard.writeText(formattedOutputText)
                    .then(() => alert('Brief metadata saved to operational clipboard.'))
                    .catch(() => fallbackClipboardEngine(formattedOutputText));
            } else {
                fallbackClipboardEngine(formattedOutputText);
            }
        }

        function fallbackClipboardEngine(text) {
            const shadowTextArea = document.createElement('textarea');
            shadowTextArea.value = text;
            shadowTextArea.style.position = 'fixed';
            shadowTextArea.style.top = '-9999px';
            document.body.appendChild(shadowTextArea);

            shadowTextArea.focus();
            shadowTextArea.select();

            try {
                const operationalStatus = document.execCommand('copy');
                if (operationalStatus) {
                    alert('Brief metadata copied via device terminal allocation.');
                } else {
                    alert('Action refused. Please select and copy input values manually.');
                }
            } catch (err) {
                alert('Action execution fault. Please handle input details manually.');
            }

            document.body.removeChild(shadowTextArea);
        }

        function executeTextDownload() {
            const outputStringPayload = serializeBriefString();
            const matchingHook = modalPostTitle.value || 'content_brief';
            const cleanIdentifier = matchingHook.replace(/[^a-z0-9]/gi, '_').toLowerCase();

            const standardBlob = new Blob([outputStringPayload], { type: 'text/plain;charset=utf-8' });
            const dynamicLinkNode = document.createElement('a');

            dynamicLinkNode.download = `${cleanIdentifier}_brief.txt`;
            dynamicLinkNode.href = window.URL.createObjectURL(standardBlob);
            dynamicLinkNode.style.display = 'none';

            document.body.appendChild(dynamicLinkNode);
            dynamicLinkNode.click();

            window.URL.revokeObjectURL(dynamicLinkNode.href);
            document.body.removeChild(dynamicLinkNode);
        }

        window.addEventListener('DOMContentLoaded', init);
    </script>
</body>
</html>

